var e={journey:{canvasLabel:`مسار الإشارة: يصل الصوت إلى ميكروفون (جهد KY-037 إلى ADC، أو أرقام INMP441 عبر I2S)، ويعالجه ESP32-S3، ويحوّله المختبر إلى شيء آخر، غالبًا صوت على مكبّر الصوت.`,optional:`{{part}} (اختياري)`,output:`← {{out}}`,path:{noMic:`(بلا ميكروفون)`,adcOrI2s:`ADC أو I2S0`,withSpeaker:`16 000/ث · خرج I2S1`},parts:{ky:`KY-037`,inmp:`INMP441`,mic:`KY-037 أو INMP441`,spk:`MAX98357A + مكبّر صوت`,wifi:`Wi-Fi (W1)`},labs:{S1:{title:`استمع`,what:`الإشارة الخام: راسم الإشارة، والميكروفونان جنبًا إلى جنب، والانحياز أو البتّات، والمقارِن`,out:`الشاشة`},S2:{title:`شدة الصوت`,what:`مقياس مستوى (dB SPL مع INMP441)، ومفكّرة لعشر دقائق، وإنذار`,out:`LED · نغمة`},S3:{title:`التحكم بالتصفيق`,what:`تصفيقات (لا أصوات بشرية) بأنماط من 1 إلى 4 تبدّل أشياء`,out:`LED · RGB · أصوات`},S4:{title:`المسجّل`,what:`تسجيل يبدأ بالصوت؛ واستمع على هاتفك أو على اللوحة`,out:`Wi-Fi · WAV · مكبّر الصوت`},S5:{title:`الطيف`,what:`FFT من صنعنا: نطاقات، وشلال، ومُوالف بنغمة مرجعية`,out:`النغمة`},S6:{title:`ألعاب الصوت`,what:`قفل بالطرق، وClap Bird، وحفلة تتبع الإيقاع`,out:`ألعاب · أصوات`},S7:{title:`مكبّر الصوت`,what:`مُركِّب صوتي: موجات ونغمات وتآلفات ومغلّفات وألحان وأصوات ألعاب`,out:`مكبّر الصوت`},S8:{title:`مؤثرات الصوت`,what:`ببغاء يكرر كلامك بصوت سنجاب أو روبوت؛ وصدى مباشر`,out:`مكبّر الصوت`}}},controls:{play:`▶ تشغيل`,pause:`❚❚ إيقاف مؤقت`,speed:`السرعة ×{{speed}}`,restart:`↺ من البداية`},sounds:{talk:`🗣 تحدّث`,whistle:`〰 صفير`,clap:`👏 تصفيق`,quiet:`🤫 هدوء`},chain:{label:`خط معالجة من ثماني مراحل من ضغط الهواء إلى الديسيبل، والمرحلة المحددة مرسومة مباشرة أدناه.`,previous:`المرحلة السابقة`,next:`المرحلة التالية`,position:`{{at}} / {{total}}`,steps:{air:{box:`الهواء`,title:`1 · الصوت هواء يتحرك`,text:`صوتك يضغط جزيئات الهواء معًا ثم يباعد بينها، مئات المرات في الثانية. يتأرجح الضغط بنحو 0.02 Pa حين تتكلم على بعد 30 cm، فوق الـ 101 325 Pa التي يحملها الهواء دائمًا. وهذا التأرجح الضئيل هو كل ما يناله الميكروفون.`},capsule:{box:`الكبسولة`,title:`2 · الكبسولة تحوّله إلى فولتات`,text:`العلبة الفضية في KY-037 كبسولة إلكتريت: رقاقة رقيقة مشحونة (الغشاء) أمام صفيحة معدنية. يحرّك الهواء الرقاقة فتتغير الفجوة، وتصنع الشحنة جهدًا من بضعة ميلي فولت. ولا مضخّم في هذه الوحدة: فما تحصل عليه بهذا الصغر.`},ao:{box:`طرف AO`,title:`3 · على طرف AO: موجة صغيرة فوق جهد ثابت كبير`,text:`تحتاج الكبسولة إلى تغذية، فيقف خرجها على جهد DC ثابت هو <b>الانحياز</b> (نحو 1.5 V هنا؛ وعرض الانحياز في S1 يريك انحيازك). والصوت تموّج من بضعة mV فوقه. وبالمقياس الحقيقي لا تراه: فالصورة المكبّرة تكبّره 100 مرة.`},adc:{box:`ADC`,title:`4 · ADC يقيسه 16 000 مرة في الثانية`,text:`يحوّل ADC الجهد إلى رقم من 0 إلى 4095. وبتوهين 12 dB يكون المدى 0-3.1 V، فالخطوة الواحدة نحو 0.76 mV والهمس بضع خطوات فقط. توهين أصغر = مدى أصغر = خطوات أدق (<code>atten</code> في S1).`},dma:{box:`DMA`,title:`5 · DMA يجمع النتائج بلا معالج`,text:`في الوضع المستمر يبدأ مؤقّت ADC نفسه كل تحويل، ويكتب DMA (النفاذ المباشر إلى الذاكرة) كل نتيجة، 4 بايتات، في RAM بنفسه. وبعد 256 نتيجة (1 KB، 16 ms) يسلّم الإطار إلى مهمة أخذ العينات على النواة 0. وحلقة الشاشة على النواة 1 لا تنتظره أبدًا.`},ring:{box:`الحلقة`,title:`6 · حلقة عينات من 4 ثوانٍ`,text:`تكتب مهمة أخذ العينات كل عينة في حلقة من 65 536 خانة في PSRAM. لكل عينة رقم تسلسلي؛ والخانة هي ذلك الرقم بمقياس 65 536، فتكتب الحلقة فوق نفسها كل 4.1 ث. ويقرأ راسم الإشارة وFFT والمسجّل مقاطع منها بالرقم متى شاؤوا.`},bias:{box:`− الانحياز`,title:`7 · أزِل الانحياز`,text:`متوسط بطيء جدًا يتبع الانحياز (يستقر في نحو ربع ثانية). وكل عينة ناقص ذلك المتوسط هي الصوت وحده: موجة حول الصفر. وقد يحرّك المقاومة المتغيرة أو وحدة مختلفة أو غرفة دافئة الانحياز؛ والمتوسط يتبعه ببساطة.`},db:{box:`int16 ← dB`,title:`8 · أرقام يفهمها برنامج الصوت`,text:`×16 تحوّل خطوات ADC إلى وحدات صوت من 16 بتًّا (من −32 768 إلى 32 767، مثل ملف WAV). وكل 64 عينة (4 ms) تقيس مهمة العينات RMS للإطار، أي متوسط القوة، ويحوّله مقياس المستوى إلى ديسيبل: مقارنةً بالمدى الكامل لـ ADC (dBFS) وبهدوء غرفتك.`}},air:{value:`مزدحم = ضغط أعلى، متفرق = أدنى · {{db, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} dB فوق الهدوء الآن`},capsule:{diaphragm:`الغشاء`,plate:`الصفيحة`,box:`خرج الكبسولة، آخر 40 ms (مربع ±30 mV)`,value:`الكبسولة الآن: {{mv, number(minimumFractionDigits: 2; maximumFractionDigits: 2; signDisplay: exceptZero)}} mV`},ao:{bias:`الانحياز {{v, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} V: الموجة في هذا الخط، أصغر من أن تُرى`,zoom:`×100 حول الانحياز (±30 mV)`,valuePlus:`AO الآن: {{v, number(minimumFractionDigits: 4; maximumFractionDigits: 4)}} V = {{bias}} mV انحياز + {{mv, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} mV من الصوت`,valueMinus:`AO الآن: {{v, number(minimumFractionDigits: 4; maximumFractionDigits: 4)}} V = {{bias}} mV انحياز − {{mv, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} mV من الصوت`},adc:{dots:`40 عينة = 2.5 ms · نقطة كل 62.5 µs · كل خط = خطوة ADC واحدة = {{mv, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} mV`,value:`الخام الآن: {{raw}} من 0-4095 · التوهين {{atten}}`},dma:{frame:`إطار DMA: 256 نتيجة × 4 بايتات`,sampler:`أخذ العينات`,samplerCore:`مهمة، النواة 0`,loopCore:`الشاشة، النواة 1`,idle:`المعالج لا يفعل شيئًا أثناء امتلاء الإطار`,value:`62.5 إطارًا في الثانية، 16 ms لكل منها · لا تستيقظ مهمة العينات إلا حين يمتلئ واحد`},ring:{write:`كتابة`,readers:{scope:`● راسم الإشارة: يقرأ آخر 20 ms`,fft:`● FFT: يقرأ آخر 512 عينة`,recorder:`● المسجّل: يقرأ نصف ثانية إلى الخلف (ما قبل التشغيل)`},size:`65 536 خانة · 128 KB من PSRAM · دورة كاملة = 4.1 ث`,value:`المكتوب = {{w, number}} · الخانة = المكتوب & 65535 = {{slot}}`},bias:{raw:`الخام (خطوات ADC) ومتوسطه البطيء: {{dc, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}}`,minus:`− المتوسط  ↓`,alone:`الصوت وحده، حول 0`,value:`الخام {{raw}} − المتوسط {{dc, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} = {{diff, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} خطوة`},db:{frames:`8 إطارات من 64 عينة (4 ms لكل منها) · ×16 = وحدات int16`,value:`سريع {{fast, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} dBFS · أرضية {{floor, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} dBFS · {{above, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} dB فوق الهدوء`}},mics:{label:`في الأعلى: المسار التناظري لـ KY-037 والمسار الرقمي لـ INMP441. وفي الأسفل: إطار I2S على أسلاك SCK وWS وSD، ومؤشر يقرأ العينة بتًّا بتًّا، والعينة وقد صارت رقمًا من 16 بتًّا.`,tickLabel:`نبضة ساعة واحدة`,tick:`نبضة ◀`,pressure:`ضغط الصوت`,pressureLabel:`قيمة العينة، كنسبة من المدى الكامل`,output:`{{s24}} (24 بتًّا)`,caption:{reading:`عند كل نبضة SCK يضع الميكروفون بتًّا واحدًا على SD؛ ويقرؤه ESP32 عند الحافة الصاعدة. ويقول WS لمن الدور: منخفض = الخانة اليسرى.`,shift:`لماذا >> 6 وليس >> 8 أكثر؟ أخذ أعلى 16 بتًّا يترك الغرفة الهادئة قرب الصفر. والاحتفاظ بـ 6 بتّات منخفضة إضافية يعني كسبًا 12 dB: يستخدم الصوت أرقامًا حقيقية، ولا يقطع إلا تصفيق عند الميكروفون مباشرة (نحو 114 dB SPL).`},lane:{capsule:`الكبسولة`,fewMv:`بضعة mV`,plusBias:`+ الانحياز`,onAo:`~1.5 V على AO`,adcBits:`12 بتًّا، 0.76 mV`,minusAverage:`− المتوسط`,dmaRing:`DMA، الحلقة`,ownAmp:`+ مضخّمه الخاص`,adc24:`ADC بـ 24 بتًّا`,insideMic:`داخل الميكروفون`,frames:`إطارات I2S`,sample24:`عينة 24 بتًّا`},frame:{left:`الخانة اليسرى (L/R ← GND: الميكروفون يتكلم هنا)`,right:`الخانة اليمنى: لا أحد (أصفار)`,firstBit:`البت 23 (الإشارة) أولًا … البت 0`,padding:`8 أصفار حشو`},read:{soFar:`المقروء حتى الآن: {{got}} من 24 بتًّا`,level:`هذا {{dbfs, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} dBFS؛ ≈ {{spl, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} dB SPL لموجة جيبية (dBFS + 111، من −26 dBFS عند 94 dB SPL في ورقة البيانات)`,clock:`SCK = 16 000 عينة × 2 خانة × 32 بتًّا = 1.024 MHz، يقودها ESP32 (I2S0)؛ ويستخدم مكبّر الصوت I2S1`}},bias:{label:`مسطرة من 0 إلى 3.3 فولت مع تظليل مدى ADC، وخط الانحياز وموجة الميكروفون؛ والأجزاء خارج المدى مقطوعة.`,bias:`الانحياز`,biasLabel:`جهد الانحياز بالميلي فولت`,sound:`الصوت`,soundLabel:`مدى علوّ الصوت: ارتفاع الموجة`,atten:`التوهين`,attenOption:`التوهين {{db}} dB`,caption:`الانحياز {{bias}} mV، والصوت ±{{a}} mV، والتوهين {{atten}}. التلميح هو نفسه الذي يطبعه عرض الانحياز في S1 على اللوحة.`,range:`مدى ADC 0-{{v, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} V`,steps:`خطوة ADC واحدة = {{mv, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} mV · تمتد هذه الموجة على {{steps}} من 4096 خطوة`,hint:{clipping:`قطع: تبلغ الموجة حافة المدى. القمم المسطحة = صوت ضائع (برتقالي)؛ والأحمر = ما قُطع.`,nearTop:`الانحياز قرب القمة: استخدم توهينًا أكبر`,try6:`تتسع في 0-1.75 V: جرّب التوهين 6 (أدق مرتين)`,try25:`تتسع في 0-1.25 V: جرّب التوهين 2.5`,good:`الموجة تتسع في المدى: جيد`}},comparator:{label:`موجة AO في آخر ثانيتين مع خط العتبة من المقاومة المتغيرة، وخرج DO تحتها: مرتفع حيثما كانت الموجة فوق الخط.`,potRange:`المقاومة المتغيرة: العتبة فوق الانحياز`,potLabel:`عتبة المقارِن بالميلي فولت فوق الانحياز`,drag:`اسحب الخط المتقطع أيضًا`,caption:`العتبة {{pot}} mV فوق الانحياز. كل قمة موجة فوق الخط المتقطع هي حافة صاعدة واحدة على DO (كهرماني)؛ والتصفيقة تصنع عشرات منها، ولهذا يصغي S3 إلى AO لا DO.`,axis:`AO ناقص الانحياز، آخر 4 ث (مقياس الجذر التربيعي)`,pot:`المقاومة {{mv}} mV`,perSecond:`{{n}}/ث`,hint:{alwaysOn:`DO مشتعل دائمًا: أدر المقاومة المتغيرة في الاتجاه الآخر`,underLine:`حتى التصفيقة تبقى تحت الخط: أعد المقاومة المتغيرة`,waiting:`لا شيء عالٍ بعد: تصفيقة قادمة`,tuned:`DO يتبع اللحظات العالية: مضبوط`}},ballistics:{label:`إعادة تشغيل مشهد صوتي: المستوى اللحظي والمقياسان السريع والبطيء وتثبيت الذروة وأرضية الضجيج عبر الزمن.`,scene:`المشهد`,scenes:{talk:`كلام ثم تصفيقة`,fan:`مروحة تُشغَّل لمدة 30 ث`},legend:{inst:`لحظي (4 ms)`,fast:`سريع 125 ms`,slow:`بطيء 1 ث`,floor:`الأرضية`,peak:`تثبيت الذروة`},now:`{{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث · {{db, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} dB فوق الهدوء`,caption:{fan:`تضيف المروحة أزيزًا ثابتًا. وترتفع الأرضية (أخضر مزرق) 0.5 dB كل ثانية حتى يصير الأزيز هو الهدوء الجديد، فيكف S2 عن وصفه بالعالي. وحين تتوقف المروحة تهبط الأرضية فورًا. وتبقى التصفيقة في النهاية بارزة.`,talk:`السريع (وردي) يتبع المقاطع؛ والبطيء (كهرماني) يعرض متوسط علوّ الكلام. والمستوى اللحظي للتصفيقة أعلى منهما بكثير: فدوّي 4 ms بالكاد يحرّك متوسط 1 ث. وتثبيت الذروة (علامات بيضاء) يمسكها 1.5 ث ثم تهبط 20 dB في الثانية.`}},decibels:{label:`موجتان: هدوء الغرفة وصوت أعلى تختاره، مع مسطرة ديسيبل تبيّن أن +6 dB يضاعف الارتفاع وأن +20 dB عشرة أضعاف.`,howLoud:`مدى العلو`,howLoudLabel:`الديسيبل فوق الهدوء، مضروبًا في عشرة`,tooTall:`(أطول من أن يُرسم: الحقيقي {{px}} px)`,legend:`رمادي = هدوء غرفتك · وردي = هذا الصوت`,marks:{quiet:`هدوء`,rustle:`حفيف`,talking:`كلام`,clap:`تصفيقة`},caption:`{{db, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} dB فوق الهدوء: الموجة أطول بـ {{ratio, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} مرة (القدرة ×{{power, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}}). يصف S2 هذا بـ «{{like}}». كل +6 dB يضاعف الارتفاع؛ و+20 dB عشرة أضعاف.`,captionBig:`{{db, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} dB فوق الهدوء: الموجة أطول بـ {{ratio, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} مرة (القدرة ×{{power, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}}). يصف S2 هذا بـ «{{like}}». كل +6 dB يضاعف الارتفاع؛ و+20 dB عشرة أضعاف.`},clapMachine:{label:`غلاف شدة الصوت على مدى 1.2 ثانية مع عتبتي الصعود والإفلات، ومؤشر، وحالات الكاشف الثلاث مع الأحداث التي أنتجها حتى الآن.`,which:`أي صوت`,back:`إطار إلى الخلف`,on:`إطار إلى الأمام`,rise:`الصعود`,riseLabel:`عتبة الصعود بالديسيبل`,release:`الإفلات`,releaseLabel:`عتبة الإفلات بالديسيبل`,sounds:{clap:`تصفيقة`,double:`تصفيقتان`,soft:`تصفيقة خفيفة`,word:`كلمة («مرحبًا»)`,whistle:`صفير`},result:{clap:`تصفيقة ({{ms}} ms، {{db, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} dB)`,long:`طويل {{ms}} ms: ليس تصفيقة`},caption:{done:`{{sound}}: {{results}}. تنتهي التصفيقة في أقل من 160 ms؛ أما الصوت البشري أو الصفير فيبقى عاليًا أطول.`,loud:`عالٍ منذ {{ms}} ms: انطلق بدء صوت فعلًا (تستخدمه الألعاب فورًا). هل هو قصير بما يكفي ليكون تصفيقة؟ انتظر حتى ينخفض تحت الإفلات.`,soft:`{{sound}}: لا شيء بعد — هذه التصفيقة لا تبلغ خط الصعود أبدًا. اخفض الصعود (أو دع learn في S3 يفعل ذلك من تصفيقاتك أنت).`,nothing:`{{sound}}: لا شيء بعد.`},states:{armed:`جاهز`,loud:`عالٍ`,quiet:`هادئ`},arrows:{onset:`≥ الصعود: بدء صوت`,end:`< الإفلات: تصفيقة أو طويل`,rearm:`هدوء 40 ms: عاد جاهزًا`}},recorder:{label:`تسع ثوانٍ من الصوت: صفقة باب وجملة، وخطا التشغيل والإبقاء، وحالة المسجّل مع حركة المؤشر: جاهز، يسجّل، ما قبل التشغيل، والمقطع الذي يُحفظ أو يُسقَط.`,back:`إلى الخلف 0.1 ثانية`,on:`إلى الأمام 0.1 ثانية`,trigger:`التشغيل`,triggerLabel:`مستوى التشغيل بالديسيبل فوق الهدوء`,hold:`الإبقاء`,holdLabel:`زمن الإبقاء بالميلي ثانية`,start:`البدء`,quiet:`هدوء`,ring:`الحلقة: آخر 4 ث موجودة دائمًا (فما قبل التشغيل مجاني)`,holding:`هادئ {{quiet, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} من {{hold, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث: إبقاء`,loud:`عالٍ: يبدأ الإبقاء من جديد`,saved:`حُفظ المقطع {{n}}: {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث`,dropped:`أُسقطت صفقة عند {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث (قصيرة جدًا)`,caption:{rec:`يسجّل. بدأ المقطع قبل التشغيل بنصف ثانية (كهرماني): ما زال المخزن الحلقي يحتفظ به. والفاصل الأقصر من الإبقاء يُبقي الجملة في مقطع واحد.`,saved:`حُفظ: ينتهي المقطع بعد نصف ثانية من آخر لحظة عالية، لا بعد الإبقاء كله. وكانت صفقة الباب عالية أيضًا، لكنها أقل من 0.4 ث: أُسقطت.`,armed:`جاهز: يصغي ولا يحتفظ بشيء غير الحلقة. وما هو أعلى من خط البدء يبدأ مقطعًا.`}},getOut:{paths:{phone:{1:{title:`افتح الصفحة`,text:`يفتح هاتفك <code>http://bench.local/</code>. الصفحة نفسها مفتوحة لكنها لا تحمل صوتًا. الصق رمز المدير (الأمر التسلسلي <code>token</code>)؛ ويبقى في sessionStorage لهذا التبويب فقط.`},2:{title:`اسرد المقاطع`,text:`<code>GET /api/clips</code> مع <code>Authorization: Bearer …</code>. وبدون الرمز: 401. كل مسار صوتي يفحصه.`},3:{title:`ابثّ مقطعًا`,text:`<code>GET /api/clip?n=3</code>: ترسل اللوحة ترويسة 44 بايتًا، ثم العينات مباشرة من PSRAM على دفعات، مع رفع الصوت (تطبيع حتى ×64) في الطريق. ولا سلسلة كبيرة واحدة في RAM أبدًا.`},4:{title:`ارسم وشغّل`,text:`تفك الصفحة WAV (WebAudio)، وترسم شكله على لوحة رسم وتشغّله مع رأس تشغيل متحرك. ويصل المستوى والحالة المباشران عبر WebSocket <code>/ws</code>.`}},board:{1:{title:`اختر مقطعًا`,text:`في عرض <b>clips</b> الضغط المطوّل يختار المقطع التالي؛ أو اكتب <code>play 3</code> (أي رقم مقطع)، و<code>play 3 0.7</code> لأبطأ وأعمق.`},2:{title:`أعلى، لكن ليس أعلى من اللازم`,text:`يُرفع صوت المقطع مثل التنزيل، لكن بحد أقصى ×16: فالهمس على KY-037 كان سيعود فحيحًا في معظمه وبأعلى حجم.`},3:{title:`خارجًا من I2S1`,text:`تذهب العينات إلى MAX98357A بسرعة <code>speed</code> × معدلها: 0.5 = نصف السرعة، أوكتاف أخفض. وأثناء التشغيل تصمّ الكواشف (حارس الصدى)؛ <code>rec</code> يوقف التشغيل أولًا، و<code>play</code> مرفوض أثناء التسجيل.`},4:{title:`ومن الهاتف أيضًا`,text:`في الصفحة <b>Play on board</b> و<b>Stop on board</b> لكل مقطع واختيار سرعة: <code>POST /api/play?n=3&speed=0.7</code> مع الرمز؛ و<code>/api/status</code> يعرض <code>playing</code> و<code>playProgress</code>.`}},usb:{1:{title:`أغلق المراقب`,text:`برنامج واحد فقط يستطيع حيازة المنفذ التسلسلي. أغلق <code>pio device monitor</code> أولًا.`},2:{title:`اطلب المقطع n`,text:`<code>uv run python tools/sound_pull.py /dev/cu.usbserial-A5069RR4 3</code> يفتح المنفذ دون إعادة ضبط اللوحة ويكتب <code>send 3</code>.`},3:{title:`أسطر Base64`,text:`ترد اللوحة بـ <code>WAV-BEGIN 3 102444 clip-3.wav</code>، ثم WAV كاملًا كنص base64، 76 حرفًا في السطر (المنفذ التسلسلي أنبوب نصي)، ثم <code>WAV-END &lt;crc32&gt;</code>. ولا يُطبع شيء آخر بينهما.`},4:{title:`افحص واحفظ`,text:`تفك الأداة الترميز، وتقارن عدد البايتات وCRC-32، وتكتب <code>clip-3.wav</code>. 100 kB تستغرق نحو 12 ث عند 115 200 baud.`}}},label:`اللوحة والهاتف وجهاز Mac، مع رسالة الخطوة الحالية وهي تنتقل بينها.`,path:`المسار`,choices:{phone:`📱 الهاتف (Wi-Fi)`,usb:`🔌 USB (تسلسلي)`,board:`🔈 مكبّر صوت اللوحة`},previous:`الخطوة السابقة`,next:`الخطوة التالية`,position:`{{at}} / {{total}}`,caption:`<b>{{n}}. {{title}}</b> {{text}}`,msg:{chunks:`WAV، دفعة بعد دفعة`,cone:`I2S1 ← الفئة D ← المخروط`},boxes:{clips:`مقاطع في PSRAM`,you:`أنت`,serialOrButton:`التسلسلي أو الزر`,speaker:`+ مكبّر صوت`,phone:`الهاتف`,browser:`المتصفح`},headline:{phone:`كل مسار صوتي يحتاج إلى الرمز · تعرض اللوحة REC أيًّا كان من بدأه`,board:`اللوحة تشغّله بنفسها: بلا هاتف ولا كبل`,usb:`لا حاجة إلى Wi-Fi · المنفذ التسلسلي USB في اللوحة، 115 200 baud`},wavLabel:`ترويسة WAV ذات الـ 44 بايتًا`,wav:{riff:`نوع الملف`,size:`102 436 = كل ما بعد هذا`,wave:`ملف موجي`,fmt:`مقطع الصيغة`,fmtLen:`طوله`,pcm:`PCM: عينات خام`,channels:`قناة واحدة (أحادي)`,rate:`عينات في الثانية`,byteRate:`بايتات في الثانية`,align:`بايتات لكل عينة`,bits:`بتّات لكل عينة`,data:`تتبعه العينات`,dataSize:`102 400 بايت = 3.2 ث`}},whistle:{label:`ست خطوات من العينات إلى اسم النغمة: العينات، والنافذة، وصناديق FFT، والصندوق الأعلى، والقطع المكافئ بين الصناديق، والنغمة مع سنتاتها.`,previous:`الخطوة السابقة`,next:`الخطوة التالية`,position:`{{at}} / {{total}}`,whistle:`الصفير`,whistleLabel:`تردد الصفير بالهرتز`,title:`{{n}} · {{title}}`,hump:`السنام: 0 عند الطرفين`,allBins:`كل الصناديق الـ 256، 0-8 kHz · تحتها: الـ 25 حول القمة`,peakBin:`الصندوق {{k}} = {{hz, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} Hz · الوضوح {{clarity, number(minimumFractionDigits: 0; maximumFractionDigits: 0)}} dB`,steps:{samples:{title:`512 عينة`,text:`أحدث 512 عينة من الحلقة: 32 ms من صفير قرب 1 760 Hz، نحو 56 موجة.`},window:{title:`× النافذة`,text:`مضروبة في سنام Hann: صفر عند الطرفين، فلا يرى FFT قفزة حيث تتكرر الكتلة.`},fft:{title:`FFT`,text:`256 صندوقًا، بينها 31.25 Hz. معظمها قرب الأرضية؛ وبضعة صناديق حول 1 760 Hz شامخة.`},peak:{title:`الصندوق الأعلى`,text:`أطول صندوق بين 80 Hz و4 kHz. ووضوحه (كم يرتفع فوق المتوسط) أكثر بكثير من 12 dB: نغمة لا ضجيج. والكلام يرسب في هذا الاختبار.`},parabola:{title:`القطع المكافئ`,text:`طبقة الصوت الحقيقية تقع بين الصناديق. وقطع مكافئ يمر بالقمة وجارَيها يضعها بينها، بدقة أعلى بكثير من 31 Hz.`},note:{title:`Hz ← نغمة`,text:`midi = 69 + 12 × log2(Hz / 440). أقرب عدد صحيح هو النغمة؛ وما تبقى × 100 هو السنتات. ±5 سنتات تظهر خضراء في المُوالف.`}}},knock:{label:`الإيقاع السري ومحاولتك مرسومين كطرقات على سطرين، ممطوطين إلى الطول نفسه، مع مقارنة الفواصل.`,intro:`اطرق إيقاعًا من 2-12 طرقة (بالزر أو بمفتاح المسافة والصورة في التركيز). انتظر 1.5 ث: يصير هو السر. ثم اطرقه من جديد، أسرع أو أبطأ.`,recording:`يسجّل: السر`,trying:`يحاول الفتح`,knock:`👊 اطرق (أو مسافة)`,startOver:`↺ ابدأ من جديد`,tolerance:`التسامح`,toleranceLabel:`التسامح بالنسبة المئوية`,saved_zero:`حُفظ السر: لا طرقات على مدى {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث. اطرقه الآن من جديد، أسرع قليلًا أو أبطأ.`,saved_one:`حُفظ السر: طرقة واحدة على مدى {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث. اطرقه الآن من جديد، أسرع قليلًا أو أبطأ.`,saved_two:`حُفظ السر: طرقتان على مدى {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث. اطرقه الآن من جديد، أسرع قليلًا أو أبطأ.`,saved_few:`حُفظ السر: {{count}} طرقات على مدى {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث. اطرقه الآن من جديد، أسرع قليلًا أو أبطأ.`,saved_many:`حُفظ السر: {{count}} طرقة على مدى {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث. اطرقه الآن من جديد، أسرع قليلًا أو أبطأ.`,saved_other:`حُفظ السر: {{count}} طرقة على مدى {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث. اطرقه الآن من جديد، أسرع قليلًا أو أبطأ.`,needTwo:`يحتاج السر إلى طرقتين أو أكثر.`,open:`مفتوح، النتيجة {{score}}: كل فاصل ضمن {{pct}}% من حصة السر، أيًّا كانت السرعة.`,locked:`مقفل: {{why}}.`,lockedWorst:`مقفل: {{why}} (أسوأ فاصل ينحرف بنسبة {{worst}}%).`,why:{noSecret:`لا سر بعد`,tooFew:`طرقات قليلة جدًا`,tooMany:`طرقات كثيرة جدًا`,off:`الإيقاع مختل`},long:`بطول {{s, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} ث`,secret:`السر`,noSecret:`لا سر بعد: اطرق واحدًا`,newSecret:`سر جديد…`,knocking:`يطرق…`,pause:`1.5 ث من الهدوء تنهي النمط`,yours:`طرقتك`},fft:{label:`صوت مكوّن من ثلاث موجات جيبية على الأكثر مع ضجيج: عيّناته في الأعلى، وتحتها صناديق FFT مع ترددات كل منها.`,tone:`النغمة {{n}}`,toneLabel:`تردد النغمة {{n}} بالهرتز (0 = متوقفة)`,off:`متوقفة`,noise:`الضجيج`,noiseLabel:`مقدار الضجيج`,size:`حجم FFT`,hann:`نافذة Hann`,caption:{windowed:`مع النافذة تكون كل نغمة قمة رفيعة وتبقى الأرضية منخفضة. جرّب نغمتين بينهما 40 Hz عند N = 256، ثم عند 1024: الصناديق الأدق تفرّق بينهما، لكن كل جواب يحتاج 64 ms من الصوت بدل 16.`,raw:`بدون النافذة لا تلتقي نهايتا العينات، وتلطّخ تلك القفزة كل نغمة على كل الصناديق (التسرّب). علّم نافذة Hann من جديد.`},samples:`{{n}} عينة = {{ms}} ms من الصوت`,samplesWindowed:`{{n}} عينة = {{ms}} ms من الصوت × نافذة Hann (متقطعة)`,bins:`الصناديق تبعد {{apart, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} Hz · {{bins}} صندوقًا حتى 8 kHz (نيكويست: نصف 16 000) · الأقوى {{hz, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} Hz = {{note}} {{cents}} سنت`},speaker:{label:`عينات تذهب إلى MAX98357A عبر I2S، ونبضاته السريعة تشغيلًا وإيقافًا التي يتبع عرضها كل عينة، ومخروط المكبّر يتبع متوسطها؛ ومنحنى للحجم؛ وخط زمني لحارس الصدى وهو يكتم الكواشف أثناء تشغيل المكبّر.`,volume:`الحجم`,volumeLabel:`الحجم من 0 إلى 100`,output:`{{vol}} ← ×{{gain, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} ({{db, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} dB)`,outputSilent:`{{vol}} ← ×{{gain, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} (صامت)`,hear:`🔈 استمع إلى 440 Hz بهذا الحجم`,caption:`الحجم {{vol}}: كل عينة × {{gain, number(minimumFractionDigits: 2; maximumFractionDigits: 2)}} قبل أن تخرج. ونبضات المضخّم أسرع من أن يتبعها المخروط، فيتبع متوسطها: الموجة.`,samples:`العينات (16 بتًّا)`,classD:`MAX98357A: تشغيل/إيقاف ~300 000 مرة في الثانية`,cone:`المخروط`,squared:`الحجم ← الشدة (مربّعًا: 50 = الربع)`,whySquared:`الحجم مربّع لأن الأذن تسمع النسب: من 100 إلى 50 هو −12 dB، أي ربع القدرة.`,whyGuard:`يتشارك الميكروفون ومكبّر الصوت الغرفة نفسها: وأثناء تشغيل المكبّر (و200 ms بعده) لا تصل إطارات إلى الكواشف. فلا يكون الصفير تصفيقة أبدًا. أما المؤثرات المباشرة في S8 فتقرأ الحلقة بدلًا من ذلك.`,guard:{title:`حارس الصدى: الميكروفون يسمع صفير اللوحة نفسها`,speaker:`مكبّر الصوت`,mic:`الميكروفون`,lab:`إلى المختبر`,muted:`مكتوم: الصفير + 200 ms`,clap:`✓ تصفيقة`}},synth:{label:`شكل الموجة، وتوافقياتها حتى 8 kHz مع التي تنطوي عائدةً عند 16 kHz بالأحمر، ومغلّف ADSR بأربعة مقابض للسحب.`,wave:`الموجة`,waves:{sine:`جيبية`,square:`مربعة`,triangle:`مثلثة`,saw:`سنّية`},keys:`المفاتيح: اعزف نغمة`,periods:`أربع دورات`,harmonics:`التوافقيات، 0-8 kHz (حد 16 kHz في اللوحة)`,adsr:`ADSR: الهجوم، والاضمحلال، والاستدامة، والإفلات`,click:`النغمة التي تبدأ أو تتوقف بأقصى ارتفاع تجعل المخروط يقفز: طقطقة. والمغلّف يُدخلها ويُخرجها تدريجيًا. اسحب المقابض ←`,what:{sine:`جيبية: تردد واحد، نقي`,square:`مربعة: توافقيات فردية 1 و3 و5…: مجوفة، مثل الكلارينت أو لعبة قديمة`,triangle:`مثلثة: توافقيات فردية، تهبط بسرعة: ناعمة، تشبه الفلوت`,saw:`سنّية: كل التوافقيات: ساطعة، طنّانة`},caption:`{{what}}.`,captionAliased_zero:`{{what}}.`,captionAliased_one:`{{what}}. على اللوحة توافقية واحدة فوق 8 kHz تنطوي عائدةً كنغمة خاطئة (أحمر): خشونة المُركِّب البسيط عند 16 kHz.`,captionAliased_two:`{{what}}. على اللوحة توافقيتان فوق 8 kHz تنطويان عائدتين كنغمتين خاطئتين (أحمر): خشونة المُركِّب البسيط عند 16 kHz.`,captionAliased_few:`{{what}}. على اللوحة {{count}} توافقيات فوق 8 kHz تنطوي عائدةً كنغمات خاطئة (أحمر): خشونة المُركِّب البسيط عند 16 kHz.`,captionAliased_many:`{{what}}. على اللوحة {{count}} توافقية فوق 8 kHz تنطوي عائدةً كنغمات خاطئة (أحمر): خشونة المُركِّب البسيط عند 16 kHz.`,captionAliased_other:`{{what}}. على اللوحة {{count}} توافقية فوق 8 kHz تنطوي عائدةً كنغمات خاطئة (أحمر): خشونة المُركِّب البسيط عند 16 kHz.`},parrot:{label:`التسجيل في الأعلى وما يشغّله الببغاء تحته، مع رأس تشغيل.`,voice:`الصوت`,fx:{normal:`عادي`,chipmunk:`سنجاب`,giant:`عملاق`,robot:`روبوت`,echo:`صدى`,reverse:`معكوس`},play:`▶ الببغاء يقولها`,record:`🎙 سجّل 3 ث بميكروفوني`,useExample:`استخدم الصوت المثال`,intro:`حُمّل صوت مثال. وصوتك أنت اختياري: لا يبدأ الميكروفون إلا حين تضغط تسجيل، ويتوقف بعد 3 ث، ولا يغادر الصوت هذه الصفحة أبدًا.`,noAudio:`هذا المتصفح بلا Web Audio.`,recording:`يسجّل من ميكروفونك لمدة 3 ث… (النقطة الحمراء تدل على ذلك)`,recorded:`سُجّل {{s, number(minimumFractionDigits: 1; maximumFractionDigits: 1)}} ث، ويبقى في هذه الصفحة فقط (رُفع صوته مثلما تفعل اللوحة). اختر صوتًا واضغط ▶.`,example:`الصوت المثال: مقطعان لفظيان مصنوعان من توافقيات مشكَّلة كحروف العلة.`,failed:{unsupported:`لا وصول إلى الميكروفون في هذا المتصفح: والصوت المثال يعمل بالطريقة نفسها.`,denied:`لم يُسمح بالميكروفون (من جهتك أو من المتصفح أو من مضيف هذه الصفحة). والصوت المثال يعمل بالطريقة نفسها.`,unreadable:`تعذّرت قراءة ذلك التسجيل: والصوت المثال ما زال هنا.`},heard:`ما سمعه`,says:`ما يقوله الببغاء ({{fx}})`,saysSpeed:`ما يقوله الببغاء ({{fx}}، بسرعة ×{{speed}})`},kit:{hands:{clap:`👏 تصفيقة`,twoClaps:`👏👏 تصفيقتان`,talk:`🗣 تحدّث 3 ث`,whistle:`〰 صفير 3 ث`,silence:`🤫 صمت`},previewCaption:`ميكروفون ومكبّر صوت تمثيليان، مرسومان كما ترسمهما اللوحة. الأزرار تقوم مقام يديك وصوتك وزر الضغط والمراقب التسلسلي؛ والنقر على الشاشة تصفيقة. يبقى صوت المتصفح مغلقًا حتى تشغّله.`,micToKy:`الميكروفون: INMP441 ← KY-037`,micToInmp:`الميكروفون: KY-037 ← INMP441`,browserOn:`🔈 استمع في المتصفح: يعمل`,browserOff:`🔈 استمع في المتصفح: متوقف`,tapHint:`انقر أو اضغط المسافة للتصفيق`,previewSoon:`المعاينة قادمة مع هذا المختبر.`,screensSoon:`قادم مع هذا المختبر.`},s1:{captions:{scope:`راسم الإشارة: آخر 20 ms من الصوت، مصطفة على عبور صفري صاعد لتقف النغمة الثابتة ساكنة. ويتبع المقياس الموجة ويُكتب بالميلي فولت عند طرف AO.`,mics:`الميكروفونات: كلاهما، أحدهما فوق الآخر (INMP441 في الأعلى): هدوء كل منهما بـ dBFS وكم يعلو الصوت عنه الآن، وكم dB أوضح يسمعه INMP441. هل وُصل واحد فقط؟ يريك كيف توصّل الآخر (ثم اضغط RST).`,bias:`الانحياز (KY-037): مسطرة 0-3.3 V. المظلَّل = مدى ADC بهذا التوهين، والخط = الانحياز، والشريط = مدى تأرجح الموجة في آخر 0.1 ث. يقول التلميح إن كان مدى أصغر سيتسع. ومع INMP441 يصير سلّمًا من بتّاته الـ 24: كم منها يستخدمه الصوت (6 dB لكل منها) وما بقي من الحيّز.`,comparator:`المقارِن: مصباح DO (مثل LED2 على الوحدة)، والحواف الصاعدة في الثانية، و6 ث من الشدة (في الأعلى) مقابل DO (في الأسفل). اضبط المقاومة المتغيرة حتى يضيء DO مع اللحظات العالية فقط. وINMP441 بلا DO: فتقارن اللوحة برمجيًا (thresh، مع تباطؤ 3 dB).`,numbers:`الأرقام: المصدر، ومعدل أخذ العينات الحقيقي، والعينات الضائعة، والمستوى بـ dBFS (و dB SPL مع INMP441)، والهدوء، وdB فوقه، وPSRAM الحرة.`},actions:{attenNext:`التوهين التالي`,freeze:`تجميد`,potMoreSensitive:`المقاومة: أكثر حساسية`,potLessSensitive:`المقاومة: أقل حساسية`}},s2:{captions:{meter:`المقياس: مع INMP441 يظهر dB SPL كبيرًا (بلا ترجيح، ±2 dB) على مقياس 30-110: 30 همس، 60 كلام، 85 خطر على السمع، 100 عالٍ. ومع KY-037: dB فوق هدوء غرفتك، وما يشبهه تقريبًا، وشريط بتثبيت الذروة (علامة بيضاء) وخط الإنذار (أحمر منقّط).`,minute:`الدقيقة: أعلى لحظة في كل ربع ثانية، لآخر 60 ث، ملوّنة بحسب الشدة؛ والخط المنقّط هو حد الإنذار.`,diary:`المفكّرة: عشر دقائق في 60 خانة من 10 ث: خط رفيع من أهدأ لحظة إلى أعلاها، وكتلة عند المتوسط، وغطاء أحمر حيث انطلق الإنذار. تاريخ مثال مع ما تفعله الآن.`,alarm:`الإنذار: جاهز أو يرنّ، والفتيل يمتلئ ما دام الصوت عاليًا (1 ث افتراضيًا)، وعدد الإنذارات وأعلاها. أي ضغطة زر تُسكته.`},actions:{loudMusic3S:`📢 موسيقى عالية 3 ث`,speedFastSlow:`السرعة سريعة/بطيئة`,buttonSilences:`الزر (يُسكت)`}},s3:{captions:{timeline:`الخط الزمني: آخر 4 ث من الشدة مع خطي الصعود (أبيض منقّط) والإفلات (رمادي منقّط). التصفيقة تنال علمًا أخضر مزرقًا؛ والصوت الطويل (كلمة أو صفير) شريطًا كهرمانيًا مكتوبًا عليه long. وفي أعلى اليسار: النمط وهو يتكوّن، ثم ما فعله.`,lamp:`المصباح: LED على GPIO 4 كمصباح، وLED الملوّن RGB ككرة بلونه. صفّق 4 مرات للحفلة.`,patterns:`الأنماط: من 1 إلى 4 تصفيقات كأزواج أيدٍ مع الإجراء الذي ينفذه كل منها؛ وآخر نمط مطابق يضيء 3 ث.`,tune:`الضبط: انقر مرتين، ثم صفّق 5 مرات كعادتك. كل عمود تصفيقة (dB فوق الهدوء، ومدة رنينها)؛ وتصير sens 60 % من أخفتها.`},actions:{threeClaps:`👏👏👏 ثلاث تصفيقات`,n4Party:`👏×4 حفلة`,learn2xOnTune:`learn (نقرتان في الضبط)`}},s4:{captions:{recorder:`المسجّل: OFF أو ARMED أو REC مع الثواني، كبيرة. آخر 3 ث من الشدة مع خط البدء: كهرماني = ما قبل التشغيل الذي أخذه المقطع من الحلقة، وأحمر = ما دخل المقطع.`,clips:`المقاطع: حتى أربعة صفوف مع شكل كل مقطع وطوله ونوعه (صوت أو يد)؛ وعلى اليمين أعلى لحظة في المقطع المختار، وكم يُرسَل أعلى صوتًا، ومتى بدأ. النقر مرتين يشغّل المقطع المختار على مكبّر صوت اللوحة؛ والضغط المطوّل هنا يختار التالي.`,web:`الويب: أين الصفحة (http://bench.local)، وعنوان IP، والإشارة، وكم صفحة مفتوحة، وكيف تحصل على الرمز. وبدون Wi-Fi محفوظ يشير إلى W1 أو sound_pull.py.`},actions:{armOnOff:`تجهيز تشغيل/إيقاف`,recStopLongPress:`تسجيل / إيقاف (ضغطة مطوّلة)`,playPicked2xOn:`▶ شغّل المختار (نقرتان في clips)`,talk2S:`🗣 تحدّث 2 ث`}},s5:{captions:{bars:`الأعمدة: 24 نطاقًا من 100 Hz إلى 8 kHz بمقياس لوغاريتمي (مثل البيانو)، بالـ dB فوق هدوء كل نطاق، مع قبعات ذروة هابطة. في الأعلى: أعلى تردد ونغمته؛ وعلى اليمين: N وHz لكل صندوق وزمن FFT.`,waterfall:`الشلال: نحو 6 ث من الطيف تتمرر إلى اليسار، والنغمات المنخفضة في الأسفل؛ ليلي ← وردي ← أبيض = 0 ← 40 dB فوق الهدوء. والصفير المنزلق يرسم خطًا.`,tuner:`المُوالف: اصفر أو دندن: النغمة كبيرة (أخضر مزرق ضمن ±5 سنت)، والتردد، ومؤشر من النشاز المنخفض إلى المرتفع، وأثر 5 ث لطبقة صوتك حول النغمة.`,steer:`التوجيه: اصفر أعلى لترفع النقطة المتوهجة وأخفض لتنزلها (600-2500 Hz، مقياس لوغاريتمي). أبقها في الحلقة ثانية لتسجّل نقطة. ويأخذ LED الملوّن RGB لون النقطة وأنت تصفر.`},actions:{slideWhistle4S:`〰 صفير منزلق 4 ث`,music3S:`🎵 موسيقى 3 ث`,hold:`تثبيت`,ref2xOnTuner:`ref (نقرتان في المُوالف)`,sweep:`مسح`}},s6:{captions:{knock:`الطرق: القفل، وإيقاع السر في الأعلى، وآخر طرقة لك تحته مع تلوين كل فاصل (أخضر مزرق قريب، كهرماني تقريبًا، مرجاني بعيد). انقر مرتين، واطرق إيقاعًا، وانتظر 1.5 ث: هذا هو السر. والفتح يرفع القيد، ويضيء LED على GPIO 4 وLED الملوّن RGB بالأخضر 5 ث.`,bird:`الطائر: Clap Bird. كل تصفيقة رفرفة؛ طِر عبر الفجوات. وفي هذه المعاينة اضغط المسافة أو انقر الشاشة للتصفيق.`,party:`الحفلة: شغّل موسيقى قرب الميكروفون (زر 🎵 هنا). كل نبضة تومض بلون جديد، وتُطلق حلقة، وتضيء LED الملوّن RGB؛ والإيقاع هو الفاصل الوسيط لآخر 8 نبضات.`},actions:{music6S:`🎵 موسيقى 6 ث`,knockSet:`knock set`,knockTheSecret:`اطرق السر (✊ ✊ ✊ … ✊ ✊)`,knockPlay:`knock play`}},s7:{captions:{wave:`الموجة: شكل موجة نغمة واحدة (أربع دورات) وطيفها 0-8 kHz. النغمة نفسها بموجة مختلفة = جرس صوتي مختلف؛ والسطر تحتها يبيّن السبب.`,keys:`المفاتيح: أوكتافان، من C4 إلى B5. تضيء النغمات وهي تعزف. النقر مرتين = النغمة التالية في السلّم، والضغط المطوّل = التآلف التالي.`,envelope:`المغلّف: منحنى ADSR (الهجوم، الاضمحلال، الاستدامة، الإفلات)؛ ونقطة تركبه أثناء عزف نغمة واحدة.`,tunes:`الألحان: القائمة على اليسار، ولفافة بيانو على اليمين تمر أمام رأس التشغيل الكهرماني. النقر مرتين يشغّل اللحن المختار، والضغط المطوّل يختار التالي.`,fx:`المؤثرات: أصوات ألعاب مبنية من وصفات (مسحات وضجيج ومرشحات)؛ وموجة آخرها كاملة مع رأس تشغيل.`},actions:{waveNext:`الموجة التالية`,tunePicked:`▶ شغّل اللحن المختار`,fxPicked:`▶ شغّل المؤثر المختار`,longPressNext:`ضغطة مطوّلة (التالي)`}},s8:{captions:{parrot:`الببغاء: قل شيئًا فيقوله لك بالصوت المختار. يصغي (تدخل أقواس)، ويسجّل (عين واسعة، REC)، ويتكلم (يتحرك المنقار مع المكبّر). وتحته: مستواك مقابل خط البدء.`,echo:`الصدى: مباشر، ميكروفون ← خط تأخير ← مكبّر صوت. تبيّن الأعمدة ما تتحول إليه تصفيقة واحدة: كل تكرار أخفت بمعامل التغذية الراجعة، وتفصل بينها مدة التأخير. وفي الأسفل: مستويا الدخل والخرج وزمن الاستجابة.`,robot:`الروبوت: مباشر، صوتك مضروبًا في موجة جيبية بطيئة (الحاملة) مع تكسير 8 بتّات؛ ويضيء الفم بما يخرج.`,scope:`راسم الإشارة: السلسلة ميكروفون ← مؤثر ← مكبّر صوت، مع ما يدخل (أخضر مزرق) وما يخرج (وردي).`},actions:{saySomething2S:`🗣 قل شيئًا (2 ث)`,fxNext:`المؤثر التالي`,again:`مرة أخرى`,echoOnOff:`الصدى تشغيل/إيقاف`,robotOnOff:`الروبوت تشغيل/إيقاف`}}};export{e as default};
